   subtype Small_Count is Natural range 0 .. 10;
   Count   : Small_Count := 3;
   Message : constant String := "café λ 東京 🚀 𝌆";

   function Doubled (Value : Integer) return Integer is
   begin
      return Value * 2;
   end Doubled;
begin
   for Index in 1 .. Count loop
